list_dashboards.code:
use WebCommander\Resources\Dashboards\Dashboards;

$response = Dashboards::listDashboards($client);

foreach ($response->map['dashboards'] as $dashboard) {
    echo $dashboard['id'], ' ', $dashboard['name'], $dashboard['default'] ? ' (default)' : '', PHP_EOL;
}

get_dashboard.code:
use WebCommander\Resources\Dashboards\Dashboards;

$response = Dashboards::getDashboard($client, '3f2b8c1e-7a4d-4e29-9b1a-5c6d7e8f9a01');

foreach ($response->map['standard_sections'] as $section) {
    echo $section['key'], $section['visible'] ? ' visible' : ' hidden', PHP_EOL;
}
